package hotel.management.system;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.sql.*;

/** Lightweight operational modules backed by the additional tables in database/hotel_upgrade.sql. */
public class FeatureModule extends JFrame {
    private final String module; private final JTable table=new JTable(); private final DefaultTableModel model=new DefaultTableModel();
    public FeatureModule(String module) {
        this.module=module; setTitle("Grand View | "+title()); setSize(1000,620); setLocationRelativeTo(null); setLayout(new BorderLayout(12,12));
        getContentPane().setBackground(new Color(246,248,251));
        JPanel head=new JPanel(new BorderLayout()); head.setBackground(new Color(18,35,55)); head.setBorder(BorderFactory.createEmptyBorder(18,22,18,22));
        JLabel h=new JLabel(title()); h.setForeground(Color.WHITE); h.setFont(new Font("SansSerif",Font.BOLD,23)); head.add(h,BorderLayout.WEST);
        JButton refresh=new JButton("Refresh"); refresh.addActionListener(e->load()); head.add(refresh,BorderLayout.EAST); add(head,BorderLayout.NORTH);
        table.setModel(model); table.setRowHeight(28); table.setAutoCreateRowSorter(true); add(new JScrollPane(table),BorderLayout.CENTER);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10)); actions.setBackground(Color.WHITE);
        JButton add=new JButton(addLabel()); add.addActionListener(e->addRecord()); actions.add(add);
        JButton update=new JButton("Update selected status"); update.addActionListener(e->updateStatus()); actions.add(update);
        JButton close=new JButton("Close"); close.addActionListener(e->dispose()); actions.add(close); add(actions,BorderLayout.SOUTH);
        load(); setVisible(true);
    }
    private String title(){switch(module){case "reservations":return "Reservations & Booking Register";case "billing":return "Billing & Invoices";case "housekeeping":return "Housekeeping Task Board";case "services":return "Guest Service Requests";default:return "Hotel Reports & Analytics";}}
    private String addLabel(){switch(module){case "reservations":return "＋ New reservation";case "billing":return "＋ New invoice";case "housekeeping":return "＋ Add task";case "services":return "＋ New service request";default:return "Export report (CSV)";}}
    private String query(){switch(module){case "reservations":return "SELECT id, guest_name, phone, room_number, check_in, check_out, guests, status, total_amount FROM reservations ORDER BY check_in DESC";case "billing":return "SELECT id, invoice_number, guest_name, room_number, amount, paid_amount, (amount-paid_amount) AS balance, payment_status, created_at FROM invoices ORDER BY created_at DESC";case "housekeeping":return "SELECT id, room_number, task, assigned_to, priority, status, updated_at FROM housekeeping_tasks ORDER BY priority DESC, updated_at DESC";case "services":return "SELECT id, guest_name, room_number, service_type, details, status, created_at FROM service_requests ORDER BY created_at DESC";default:return "SELECT 'Rooms' AS metric, COUNT(*) AS value FROM room UNION ALL SELECT 'Customers', COUNT(*) FROM customer UNION ALL SELECT 'Reservations', COUNT(*) FROM reservations UNION ALL SELECT 'Invoices', COUNT(*) FROM invoices UNION ALL SELECT 'Open housekeeping tasks', COUNT(*) FROM housekeeping_tasks WHERE status <> 'DONE' UNION ALL SELECT 'Open service requests', COUNT(*) FROM service_requests WHERE status <> 'DONE'";}}
    private void load(){try(conn c=new conn()){if(c.c==null)throw new SQLException("Database connection unavailable");try(Statement s=c.c.createStatement();ResultSet rs=s.executeQuery(query())){model.setRowCount(0);model.setColumnCount(0);ResultSetMetaData md=rs.getMetaData();for(int i=1;i<=md.getColumnCount();i++)model.addColumn(md.getColumnLabel(i));while(rs.next()){Object[] row=new Object[md.getColumnCount()];for(int i=1;i<=row.length;i++)row[i-1]=rs.getObject(i);model.addRow(row);}}}catch(Exception ex){model.setRowCount(0);model.setColumnCount(0);model.addColumn("Setup required / database message");model.addRow(new Object[]{ex.getMessage()});model.addRow(new Object[]{"Run database/hotel_upgrade.sql and configure database credentials in HOTEL_DB_* environment variables."});}}
    private void addRecord(){if(module.equals("reports")){JOptionPane.showMessageDialog(this,"Reports are shown in the table. Select and copy rows to a spreadsheet.");return;}try(conn c=new conn()){if(c.c==null)throw new SQLException("Database connection unavailable");switch(module){case "reservations": addReservation(c.c);break;case "billing":addInvoice(c.c);break;case "housekeeping":addHousekeeping(c.c);break;case "services":addService(c.c);break;}load();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Could not save record: "+ex.getMessage(),"Save failed",JOptionPane.ERROR_MESSAGE);}}
    private String ask(String label){return JOptionPane.showInputDialog(this,label);}
    private void addReservation(Connection c)throws Exception{String guest=ask("Guest full name:");if(blank(guest))return;String phone=ask("Phone:");String room=ask("Room number:");String in=ask("Check-in date (YYYY-MM-DD):");String out=ask("Check-out date (YYYY-MM-DD):");String amount=ask("Total amount:");try(PreparedStatement p=c.prepareStatement("INSERT INTO reservations(guest_name,phone,room_number,check_in,check_out,guests,status,total_amount) VALUES(?,?,?,?,?,?,?,?)")){p.setString(1,guest);p.setString(2,phone);p.setString(3,room);p.setDate(4,Date.valueOf(in));p.setDate(5,Date.valueOf(out));p.setInt(6,1);p.setString(7,"BOOKED");p.setBigDecimal(8,new java.math.BigDecimal(amount));p.executeUpdate();}}
    private void addInvoice(Connection c)throws Exception{String guest=ask("Guest full name:");if(blank(guest))return;String room=ask("Room number:");String amount=ask("Invoice amount:");String paid=ask("Amount paid:");try(PreparedStatement p=c.prepareStatement("INSERT INTO invoices(invoice_number,guest_name,room_number,amount,paid_amount,payment_status) VALUES(?,?,?,?,?,?)")){p.setString(1,"GV-"+System.currentTimeMillis());p.setString(2,guest);p.setString(3,room);java.math.BigDecimal a=new java.math.BigDecimal(amount),b=new java.math.BigDecimal(paid);p.setBigDecimal(4,a);p.setBigDecimal(5,b);p.setString(6,b.compareTo(a)>=0?"PAID":b.signum()>0?"PARTIAL":"UNPAID");p.executeUpdate();}}
    private void addHousekeeping(Connection c)throws Exception{String room=ask("Room number:");if(blank(room))return;String task=ask("Task (e.g. Deep clean):");String who=ask("Assigned staff:");String priority=ask("Priority (LOW, NORMAL, HIGH):");try(PreparedStatement p=c.prepareStatement("INSERT INTO housekeeping_tasks(room_number,task,assigned_to,priority,status) VALUES(?,?,?,?,?)")){p.setString(1,room);p.setString(2,task);p.setString(3,who);p.setString(4,priority==null?"NORMAL":priority.toUpperCase());p.setString(5,"OPEN");p.executeUpdate();}}
    private void addService(Connection c)throws Exception{String guest=ask("Guest name:");if(blank(guest))return;String room=ask("Room number:");String type=ask("Service type (Room service / Laundry / Maintenance):");String details=ask("Request details:");try(PreparedStatement p=c.prepareStatement("INSERT INTO service_requests(guest_name,room_number,service_type,details,status) VALUES(?,?,?,?,?)")){p.setString(1,guest);p.setString(2,room);p.setString(3,type);p.setString(4,details);p.setString(5,"OPEN");p.executeUpdate();}}
    private void updateStatus(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a record first.");return;}if(module.equals("reports")){return;}Object id=table.getValueAt(table.convertRowIndexToModel(row),0);String status=ask("Enter new status (e.g. BOOKED, CHECKED_IN, DONE, CANCELLED):");if(blank(status))return;String sql;switch(module){case "reservations":sql="UPDATE reservations SET status=? WHERE id=?";break;case "billing":sql="UPDATE invoices SET payment_status=? WHERE id=?";break;case "housekeeping":sql="UPDATE housekeeping_tasks SET status=?, updated_at=CURRENT_TIMESTAMP WHERE id=?";break;default:sql="UPDATE service_requests SET status=? WHERE id=?";}
        try(conn c=new conn()){if(c.c==null)throw new SQLException("Database connection unavailable");try(PreparedStatement p=c.c.prepareStatement(sql)){p.setString(1,status.toUpperCase());p.setObject(2,id);p.executeUpdate();}load();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Update failed: "+ex.getMessage());}}
    private boolean blank(String s){return s==null||s.trim().isEmpty();}
}
